const promise = new Promise((resolve, reject) => {
  // Initially: pending

  setTimeout(() => {
    resolve("Success");
    // Now: fulfilled
  }, 1000);
});

// If reject() were called instead:
// The Promise would become rejected.

const success = new Promise((resolve, reject) => {
  resolve("Success");
});

const failure = new Promise((resolve, reject) => {
  reject(new Error("Something went wrong"));
});

success.then(value => console.log(value));
// Success

failure.catch(error => console.log(error.message));
// Something went wrong

